</head>
<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Developer basics</p>
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="intro">Choose every answer that applies. Some questions have more than one correct choice.</p>

      <form id="quiz-form">
        <div class="form-field">
          <label class="question-title" id="question-1">1. Which of these are programming languages?</label>
          <p class="help-text" id="question-1-help">Select all options that are general-purpose languages used to write software.</p>
          <div class="choices" role="group" aria-labelledby="question-1" aria-describedby="question-1-help">
            <label class="choice">
              <input type="checkbox" name="q1" value="python">
              <span>Python</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="html">
              <span>HTML</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="java">
              <span>Java</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="css">
              <span>CSS</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <label class="question-title" id="question-2">2. Which languages are commonly used for web development?</label>
          <div class="choices" role="group" aria-labelledby="question-2">
            <label class="choice">
              <input type="checkbox" name="q2" value="javascript">
              <span>JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="typescript">
              <span>TypeScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="php">
              <span>PHP</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="sql">
              <span>SQL</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <label class="question-title" id="question-3">3. Which languages are often used for systems programming?</label>
          <div class="choices" role="group" aria-labelledby="question-3">
            <label class="choice">
              <input type="checkbox" name="q3" value="c">
              <span>C</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="rust">
              <span>Rust</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="go">
              <span>Go</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="scratch">
              <span>Scratch</span>
            </label>
          </div>
        </div>

        <button type="submit">Submit answers</button>
        <p class="result" id="result" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const quizForm = document.querySelector("#quiz-form");
    const result = document.querySelector("#result");

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedAnswers = new FormData(quizForm);
      let selectedCount = 0;

      for (const answer of selectedAnswers.values()) {
        selectedCount += 1;
      }

      result.textContent = selectedCount
        ? `Thanks! You selected ${selectedCount} answer${selectedCount === 1 ? "" : "s"}.`
        : "Select at least one answer before submitting.";
    });
  </script>
</body>
</html>
